//! Registry CLI commands for discovering and installing extensions.use clap::Subcommand;use crate::registry::catalog::RegistryCatalog;use crate::registry::installer::RegistryInstaller;use crate::registry::manifest::ManifestKind;#[derive(Subcommand, Debug, Clone)]pub enum RegistryCommand {    /// List available extensions in the registry    List {        /// Filter by kind: "tool" or "channel"        #[arg(short, long)]        kind: Option<String>,        /// Filter by tag (e.g. "default", "google", "messaging")        #[arg(short, long)]        tag: Option<String>,        /// Show detailed information        #[arg(short, long)]        verbose: bool,    },    /// Show detailed information about an extension or bundle    Info {        /// Extension or bundle name (e.g. "slack", "google", "tools/gmail")        name: String,    },    /// Install an extension or bundle from the registry    Install {        /// Extension or bundle name (e.g. "slack", "google", "default")        name: String,        /// Force overwrite if already installed        #[arg(short, long)]        force: bool,        /// Build from source instead of downloading pre-built artifact        #[arg(long)]        build: bool,    },    /// Install the default bundle of recommended extensions    InstallDefaults {        /// Force overwrite if already installed        #[arg(short, long)]        force: bool,        /// Build from source instead of downloading pre-built artifact        #[arg(long)]        build: bool,    },}/// Run a registry command.pub async fn run_registry_command(cmd: RegistryCommand) -> anyhow::Result<()> {    // For install commands that need to build from source, a disk registry is required.    // For list/info, embedded manifests suffice.    let registry_dir = RegistryCatalog::find_dir();    let catalog = if let Some(ref dir) = registry_dir {        RegistryCatalog::load(dir)?    } else {        RegistryCatalog::load_or_embedded()?    };    // Resolve repo root for installer (empty path when running from binary)    let repo_root = registry_dir        .as_ref()        .and_then(|d| d.parent().map(|p| p.to_path_buf()))        .unwrap_or_default();    match cmd {        RegistryCommand::List { kind, tag, verbose } => {            cmd_list(&catalog, kind.as_deref(), tag.as_deref(), verbose)        }        RegistryCommand::Info { name } => cmd_info(&catalog, &name),        RegistryCommand::Install { name, force, build } => {            cmd_install(&catalog, &repo_root, &name, force, build).await        }        RegistryCommand::InstallDefaults { force, build } => {            cmd_install(&catalog, &repo_root, "default", force, build).await        }    }}